class SafetyReport { const SafetyReport({required this.id,required this.location,required this.latitude,required this.longitude,required this.category,required this.description,required this.status,required this.createdAt}); final int id; final String location,category,description,status; final double latitude,longitude; final DateTime createdAt; factory SafetyReport.fromJson(Map<String,dynamic> j)=>SafetyReport(id:(j['id'] as num).toInt(),location:j['location'].toString(),latitude:(j['latitude'] as num).toDouble(),longitude:(j['longitude'] as num).toDouble(),category:j['category'].toString(),description:j['description'].toString(),status:j['status'].toString(),createdAt:DateTime.parse(j['createdAt'].toString())); }
